using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
namespace Snowglow.Editor {
 public static class AlpsRebuildAssets {
  public const string Source="Assets/Snowglow/Catalog/Sources/AlpsRebuild/";
  [Serializable] public class Export {public Item[] assets;}
  [Serializable] public class Item {public string slug,kind,palette;public string[] parts;public float[] size;}
  static void Check(bool b,string m){if(!b)throw new InvalidOperationException("Alps rebuild intake: "+m);}
  static Material Material(Item a,string part){bool windows=part=="Windows"&&a.kind!="Landmark";string name=windows?"WarmWindows":a.palette;string path=Source+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m)return m;m=new Material(Shader.Find(windows?"Universal Render Pipeline/Unlit":"Universal Render Pipeline/Simple Lit")){name="Alps rebuild | "+name,enableInstancing=true};m.SetColor("_BaseColor",windows?new Color(1,.78f,.40f):Color.white);if(!windows)m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Source+a.palette+".png"));m.SetFloat("_Smoothness",0);m.SetColor("_SpecColor",Color.black);m.SetFloat("_Cull",2);AssetDatabase.CreateAsset(m,path);return m;}
  public static void RefineLandmarkWindows(){var a=Find("GateTower");if(!a)return;string path=AssetDatabase.GetAssetPath(a.prefab);var g=PrefabUtility.LoadPrefabContents(path);try{foreach(var r in g.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name=="Windows"))r.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(Source+"LandmarkPalette.mat");PrefabUtility.SaveAsPrefabAsset(g,path);}finally{PrefabUtility.UnloadPrefabContents(g);}}
  public static CatalogAsset Find(string slug)=>CatalogPreparation.Library().Find("alps-rebuild-"+slug.ToLowerInvariant());
  public static void Install(){Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");Directory.CreateDirectory("Logs/AlpsRebuild");string library=CatalogPreparation.LibraryPath;if(!File.Exists("Logs/AlpsRebuild/Catalog-before.asset"))File.Copy(library,"Logs/AlpsRebuild/Catalog-before.asset");var rows=JsonUtility.FromJson<Export>(File.ReadAllText(Source+"ExportMetrics.json")).assets;Check(rows.Length==22,"22 source assemblies");var report=new System.Text.StringBuilder();int total=0;
   foreach(var row in rows){var entry=Find(row.slug);if(entry){report.AppendLine("Retained prepared entry "+entry.id);continue;}string path=Source+row.slug+".fbx";var importer=AssetImporter.GetAtPath(path)as ModelImporter;Check(importer!=null,"import "+path);importer.importAnimation=false;importer.importCameras=false;importer.importLights=false;importer.isReadable=false;importer.globalScale=1;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;foreach(string part in row.parts)importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"Rebuild_"+row.palette+"_"+part),Material(row,part));importer.SaveAndReimport();
    var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);Check(model,"model "+path);var b=CatalogValidation.BoundsOf(model);var expected=new Vector3(row.size[0],row.size[1],row.size[2]);Check((b.size-expected).magnitude<.15f,"metre scale "+row.slug+" got "+b.size+" expected "+expected);bool landscape=row.kind=="Mountain"||row.kind=="Terrain";var kind=landscape?CatalogKind.Landscape:CatalogKind.BuildingAssembly;var draft=CatalogPreparation.Draft(row.slug,kind,AssetSource.ImportedModel,null,"User supplied Blender; source checksum manifest SourceAssets/AlpsRebuild/Provenance.json. Evaluated export copies; embedded text not executed.");draft.id="alps-rebuild-"+row.slug.ToLowerInvariant();draft.creationSourcePath="SourceAssets/AlpsRebuild/"+(row.kind=="Terrain"?"Snow_District_Alps_Town_Terrain.blend":row.kind=="Mountain"?"Snow_District_Alps_Mountains.blend":row.kind=="Building"?"Snow_District_Alps_Buildings.blend":"Snow_District_Statue_and_Tower.blend");entry=CatalogPreparation.Prepare(model,kind,row.slug,1,Vector3.zero,AssetSource.ImportedModel,draft.provenance,draft,landscape);
    var prefab=PrefabUtility.LoadPrefabContents(AssetDatabase.GetAssetPath(entry.prefab));try{var front=prefab.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Front");var origin=front.parent.TransformPoint(Vector3.zero);var facing=prefab.transform.InverseTransformDirection(front.position-origin);Check(Mathf.Abs(facing.y)<.001f&&Mathf.Abs(facing.z)>.99f,"front basis "+row.slug);if(facing.z<0)prefab.transform.Find("VisualRoot").localRotation=Quaternion.Euler(0,180,0);foreach(var t in prefab.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="Front"||t.name.StartsWith("Basis")).ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);
     if(!landscape){var bounds=CatalogValidation.BoundsOf(prefab);CatalogPreparation.Anchor(prefab.transform,"entrance",AnchorRole.Entrance,new Vector3(0,0,bounds.max.z));if(row.slug=="GateTower"){foreach(var c in prefab.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);var f=prefab.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Architecture");f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;}}
     foreach(var r in prefab.GetComponentsInChildren<MeshRenderer>(true))r.gameObject.isStatic=true;PrefabUtility.SaveAsPrefabAsset(prefab,AssetDatabase.GetAssetPath(entry.prefab));
    }finally{PrefabUtility.UnloadPrefabContents(prefab);}entry.tags=new[]{"alps-rebuild",row.kind.ToLowerInvariant(),"opaque-shared-palette","editor-authored"};entry.minimumScale=landscape?.05f:.6f;entry.maximumScale=landscape?1:2;entry.visualReviewed=false;entry.status=PreparationStatus.NeedsReview;entry.assumptions="Metres, Y up, prepared front +Z. One box per building; GateTower uses static nonconvex collision preserving its real arch. Mountain LOD1 only (696 triangles). Source palette UVs retained, opaque warm windows; separately removable snow. Needs phone/scene acceptance before Ready.";CatalogPreparation.RecordMetrics(entry);EditorUtility.SetDirty(entry);total+=entry.triangles;report.AppendLine(entry.id+" | "+entry.triangles+" triangles | "+entry.renderers+" renderers | "+entry.localBounds.size+" | "+entry.status);
   }AssetDatabase.SaveAssets();Check(rows.All(r=>Find(r.slug)&&Find(r.slug).prefab),"all prepared prefabs saved");File.WriteAllText("Logs/AlpsRebuild/AssetIntake.txt","PASS:22 reusable catalogue assemblies prepared; source files preserved. New prepared triangle sum "+total+". Entries remain NeedsReview.\n"+report);}
 }
}

namespace Snowglow.Editor {
 [InitializeOnLoad] public static class AlpsRebuildAuthoring {
  const string Log="Logs/AlpsRebuild",Folder="Assets/Snowglow/Levels/TheAlps/Rebuild20261117",ScenePath="Assets/Scenes/TheAlps.unity";
  static AlpsRebuildAuthoring(){EditorApplication.update+=Pending;}
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<T>(true)).ToArray();
  static void Check(bool b,string m){if(!b)throw new InvalidOperationException("Alps rebuild: "+m);}
  static void Pending(){if(!File.Exists(Log+".request")||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;string a=File.ReadAllText(Log+".request").Trim();File.Delete(Log+".request");Directory.CreateDirectory(Log);try{if(a=="inspect")Inspect();else if(a=="assets")AlpsRebuildAssets.Install();else if(a=="build")AlpsRebuildScene.Build();else if(a=="twelvemountains")AlpsRebuildScene.ReviseTwelveMountains();else if(a=="townedgehillsretry")AlpsRebuildScene.RetryTownEdgeHills();else if(a=="townedgehills")AlpsRebuildScene.BringHillsToTownEdge();else if(a=="kilometrehorizon")AlpsRebuildScene.FitMountainsToKilometre();else if(a=="furthermountains")AlpsRebuildScene.MoveMountainsFurther();else if(a=="rollinghills")AlpsRebuildScene.RollingOuterHills();else if(a=="outerbelt")AlpsRebuildScene.InsetHillsOuterMountains();else if(a=="mountains")AlpsRebuildScene.FixMountainBases();else if(a=="finish")AlpsRebuildScene.Finish();else if(a=="polish")AlpsRebuildScene.Polish();else if(a=="refine")AlpsRebuildScene.Refine();else if(a=="audit")AlpsRebuildScene.Audit();else if(a=="review")AlpsRebuildScene.Review();else throw new InvalidOperationException("Unknown rebuild action "+a);}catch(Exception e){File.WriteAllText(Log+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static void Inspect(){var active=SceneManager.GetActiveScene();var source=SceneManager.GetSceneByPath("Assets/Scenes/Pinefall.unity");bool close=!source.IsValid();if(close)source=EditorSceneManager.OpenScene("Assets/Scenes/Pinefall.unity",OpenSceneMode.Additive);try{var t=All<Terrain>(source).Single();var d=t.terrainData;var edges=Enumerable.Range(0,101).SelectMany(i=>new[]{d.GetInterpolatedHeight(i/100f,0),d.GetInterpolatedHeight(i/100f,1),d.GetInterpolatedHeight(0,i/100f),d.GetInterpolatedHeight(1,i/100f)}).OrderBy(x=>x).ToArray();File.WriteAllText(Log+"/SceneInspection.txt","Active "+active.path+" dirty="+active.isDirty+"; roots="+string.Join(";",active.GetRootGameObjects().Select(g=>g.name))+"\nPinefall heightmap="+d.heightmapResolution+" terrain size="+d.size+" base="+t.transform.position+" edge min="+edges.First()+" median="+edges[edges.Length/2]+" p95="+edges[(int)(edges.Length*.95f)]+" max="+edges.Last()+"\n");File.WriteAllLines(Log+"/PinefallPlacements.txt",All<CatalogPlacement>(source).Where(p=>!(p.assetId??"").StartsWith("alpine-tree-")).Select(p=>p.placementId+" | "+p.assetId+" | "+p.transform.position+" | "+p.transform.eulerAngles+" | "+CatalogValidation.BoundsOf(p.gameObject)));}finally{if(close)EditorSceneManager.CloseScene(source,true);SceneManager.SetActiveScene(active);}}
 }
}

